    supplied object catching all exceptions.
    Also tries to call release_conn() in case a requests raw stream
    :param closable: The object to be closed
    :rtype: None
    """
    try:
        closable.close()
    except Exception:
        pass
    try:
        closable.release_conn()
    except Exception:
        pass

